-- AI-generated executive reports table
-- Stores reports generated by the scheduled report cron job and /reports/generate endpoint

CREATE TABLE IF NOT EXISTS ai_reports (
  id VARCHAR(36) NOT NULL,
  user_id VARCHAR(36) NOT NULL,
  report_type VARCHAR(50) NOT NULL DEFAULT 'executive_summary',
  title VARCHAR(500) NOT NULL,
  content LONGTEXT NOT NULL,
  content_chars INT NOT NULL DEFAULT 0,
  email_delivered TINYINT(1) NOT NULL DEFAULT 0,
  email_delivered_at TIMESTAMP NULL,
  tokens_used INT NULL,
  latency_ms INT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  INDEX idx_ar_user_id (user_id),
  INDEX idx_ar_user_created (user_id, created_at DESC),
  INDEX idx_ar_type_user (report_type, user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
